function hanyaAngka(teks) {
  return teks.replace(/\D/g, "");
}
function kodePosValid(teks) {
  return /^\d{5}$/.test(teks);
}
console.log(hanyaAngka("(021) 555-0199"));
console.log(kodePosValid("40115"));
console.log(kodePosValid("40115a"));
